        note: ACADEMIC_NOTE,
        isProse: true,
        rimasInternas,
        verses: [],
        scans: [],
        metrics: [],
        uniqueMetrics: [],
        isIsometric: false,
        rhymes: [],
        rhymePairs: [],
        rhymeScheme: "",
        stanzas: [],
        totalVerses: 0,
        dominantMetric: null,
        dominantName: "",
