      note: ACADEMIC_NOTE,
      isProse: false,
      verses,
      scans,
      metrics,
      uniqueMetrics,
      isIsometric,
      rhymes,
      rhymeScheme: scheme,
      stanzas,
      totalVerses: verses.length,
